"C:\\Program Files\\PowerShell\\7\\pwsh.exe" -NoProfile -Command '$ErrorActionPreference='"'Stop'
if((Get-Location).Path-ne'D:\\EliteSync-v10'){throw 'CWD'}
if((git branch --show-current)-ne'main'-or(git rev-parse HEAD)-ne'cf8bfaa4a03b8c9a682105617b185141904413be'){throw 'GIT'}
"'$s=Get-Content -LiteralPath '"'EVIDENCE/APP-M5-78-OWN-ROOT-BOOTSTRAP-CONTRACT/workspace-before.json' -Raw|ConvertFrom-Json
"'$now=@(git -c core.quotepath=false status --porcelain=v1 --untracked-files=all|ForEach-Object{$_.Substring(3)})
$missing=@($s.Paths|Where-Object{$_ -notin $now})
if($s.Count-ne235-or$s.Paths.Count-ne235-or$missing.Count-ne0){throw '"'SNAPSHOT'}
if(Test-Path -LiteralPath 'EVIDENCE/APP-M5-78-OWN-ROOT-BOOTSTRAP-CONTRACT/bootstrap-contract.md'){throw 'TARGET_EXISTS'}
"'$paths=@('"'apps/android_synthetic_demo/tools/aar_entry_materials.py','EVIDENCE/APP-M5-77-LOCAL-KOTLIN-ATTACHMENT-BINDING-AUDIT/binding-audit.md')
"'$sizes=@(20338,8054)
$hashes=@('"'B324943D7CC88EB714DD19450E0E9A2853609580C3A6F9FBFACAC0DA11D04DD7','23D98E302054511E43BC9E97DC380135641BE6B5BFDE0E57D5809EB9E5C5968D')
"'$utf=[Text.UTF8Encoding]::new($false,$true)
$parts=[Collections.Generic.List[string]]::new()
for($i=0;$i-lt2;$i++){
$f=Get-Item -LiteralPath $paths[$i]
if($f-isnot[IO.FileInfo]-or($f.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){throw '"'FILE'}
"'$d=$f.Directory
while($null-ne$d){if(($d.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){throw '"'ANCESTOR'};"'$d=$d.Parent}
if($f.Length-ne$sizes[$i]){throw '"'SIZE'}
"'$b=[IO.File]::ReadAllBytes($f.FullName)
$sha=[Security.Cryptography.SHA256]::Create()
try{$h=[BitConverter]::ToString($sha.ComputeHash($b)).Replace('"'-','')}finally{"'$sha.Dispose()}
if($h-ne$hashes[$i]){throw '"'HASH'}
"'$t=$utf.GetString($b)
$parts.Add("SOURCE $($i+1) path=$($paths[$i]) bytes=$($b.Length) hash=$h reads=1 ordinaryFullAncestors=true strictUTF8=true")
if($i-eq0){$lines=$t.Split([char]10);for($j=0;$j-lt$lines.Length;$j++){if(($j-ge32-and$j-le109)-or$j-ge169){$parts.Add(('"'{0}: {1}'-f("'$j+1),$lines[$j].TrimEnd([char]13)))}}}else{$parts.Add($t)}
}
$body=[string]::Join([Environment]::NewLine,$parts)
$prefix="A_OK branch=main HEAD=cf8bfaa4a03b8c9a682105617b185141904413be old=235 missing=0 status=$($now.Count) sourceReads=2 targetAbsent=true"
$out=$prefix+[Environment]::NewLine+$body
$receipt="OUTPUT_BYTES=$($utf.GetByteCount($out)) OUTPUT_CHARS=$($out.Length) limits=16384/18000"
$out=$receipt+[Environment]::NewLine+$out
if($utf.GetByteCount($out)-gt16384-or$out.Length-gt18000){throw '"'OUTPUT_LIMIT'}
[Console]::WriteLine("'$out)'
